WITH parsed AS (SELECT id, customer_id, created_at, items, COALESCE(ship_to.zip, 'UNKNOWN') AS zip_or_unknown, EXISTS(coupon_codes, c -> c LIKE 'W%') AS has_welcome_code, COALESCE(attributes['gift'], 'unknown') AS gift_or_default, attributes['device'] AS device, ship_to.country AS ship_country FROM carts) SELECT DATE_TRUNC('HOUR', created_at) AS hour_window, COUNT_IF(ship_country = 'UK') AS uk_events, MAX(created_at) AS last_seen, COUNT(*) AS num_rows FROM parsed GROUP BY DATE_TRUNC('HOUR', created_at)
